import{TASKS06,EXERCISES06,decodeSP06,assess06,checkExercise06,STD_SP06,MULTI_SP06,describeError02}from'./sp06.mjs';import{board}from'../lessons/02/teaching/visuals.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function lab06Page({code,task,quizBlock=''}){return`<main id="main" class="wrap focused-lesson"><header class="focused-hero"><div class="breadcrumbs"><a href="../../index.html">课程</a> / Lab 06</div><h1>两行字母，决定上下左右</h1><p class="lead">从两个排列建出约束图，用最长路径算出最小可行坐标。</p><nav class="focused-nav" aria-label="本课学习路径"><a href="#video">01 互动教学</a><a href="#lab">02 综合 Lab · Python</a><a href="#quiz">03 课后习题</a></nav></header>
<section id="video" class="focused-section"><span id="film"></span><span class="eyebrow">01 / LEARN</span><h2>互动讲解</h2><p class="small">先看一遍；两行次序、约束图与坐标会按推理切换。</p><iframe id="interactive-teaching-frame" title="Lab6互动教学" src="teaching/?embed=1&v=sp-1" allow="autoplay; fullscreen" scrolling="no" style="width:100%;height:850px;border:0;display:block"></iframe></section>
<section id="lab" class="focused-section"><span class="eyebrow">02 / CLASSIFY · SOLVE · CONSTRUCT</span><h2>编码实验台</h2><p>三项任务：手算多前驱坐标、构造不重叠但越界的编码、找到同一布局的两份编码。</p><label>选择任务 <select id="lab06-task">${TASKS06.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><p id="lab06-prompt"></p><button id="lab06-reset">重置当前任务</button>
<div class="lab04-console"><label>pos（第一行） <input id="lab06-pos" class="wide-input" spellcheck="false"></label><label>neg（第二行） <input id="lab06-neg" class="wide-input" spellcheck="false"></label><button id="lab06-decode" class="primary">解码并建图</button><p id="lab06-parse" role="status"></p></div>
<div id="lab06-board" class="lab02-board"></div><div class="lab04-side"><div id="lab06-graph"></div><div id="lab06-coords"></div></div><div id="lab06-metrics"></div>
<div id="lab06-evidence"></div><label>写下你的推理（谁约束谁、关键前驱是谁）<textarea id="lab06-explanation" rows="3" style="display:block;width:100%"></textarea></label><button id="lab06-check" class="primary">检查并保存</button> <button id="lab06-hint">需要一点提示</button><p id="lab06-result" role="status" style="white-space:pre-line"></p>
<article id="python" class="python-integrated"><h3>Python Lab：实现完整解码器 decode_sequence_pair</h3><p>${esc(task.prompt.zh)}</p><details><summary>接口合同与错误码</summary><p>pos、neg 是模块 id 的序列（列表或字符串），两者都必须恰好包含清单里的每个模块一次。分类规则：i 在 pos 中先于 j 且在 neg 中也先于 j → 水平边 (i,j)，约束 x_j ≥ x_i + w_i；neg 中次序相反 → 竖直边 (i,j)，约束 y_j ≥ y_i + h_i。边权是前驱的尺寸。按 pos（本身就是拓扑序）逐点取最大值。返回 {'ok','errors','graph':{'H','V'},'order','coords','rows','key'}；key[id]={'x':argmax,'y':argmax}。错误码：permutation:pos / permutation:neg。</p><p>${task.tests.length}项检查是基线。再写一个自己的测试并说明它能排除哪种错误实现（例如"只连相邻元素"或"把下界相加"）。</p></details><textarea id="python-source" class="python-editor" aria-label="Python source code" spellcheck="false">${esc(code)}</textarea><div class="python-toolbar"><button id="python-run" class="primary">运行综合检查</button><button id="python-stop" disabled>停止</button><button id="python-reset">恢复模板</button></div><pre id="python-output" class="python-output" role="status">尚未检查。修改代码后，需要重新运行。</pre></article></section>
<section id="quiz" class="focused-section"><span class="eyebrow">03 / TRANSFER · COUNTEREXAMPLE · BOUNDARY</span><h2>课后练习：把理由说清楚</h2><p>除了数值，也写出推理。做完后可以对照参考要点检查。</p>${EXERCISES06.map(q=>`<article class="extended-exercise" data-exercise06="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="exercise-fields">${q.fields.map(([key,label])=>`<label>${esc(label)} <input type="number" step="any" data-field="${key}"></label>`).join('')}</div><label>你的推理<textarea data-explain rows="3"></textarea></label><button data-check>检查并保存</button> <button data-reveal>查看参考要点</button><p data-result role="status"></p><p data-rubric hidden>${esc(q.rubric)}</p></article>`).join('')}${quizBlock}</section></main>`;}
export function bindLab06({progress,save}){const $=s=>document.querySelector(s);let task=TASKS06[0],result=null,edited=false,hint=false;
 progress.lab06Submissions=progress.lab06Submissions||{};progress.exercises06=progress.exercises06||{};
 function render(){$('#lab06-prompt').textContent=task.prompt;$('#lab06-pos').value=task.pos;$('#lab06-neg').value=task.neg;
  $('#lab06-parse').textContent=result?(result.ok?`解码成功：约束 ${result.graph.H.length} 条水平 + ${result.graph.V.length} 条竖直；顺序 ${result.order.join(' → ')}`:'解码失败：'+result.errors.join('；')):'点击"解码并建图"开始。';
  const rows=result&&result.ok?result.rows:decodeSP06(STD_SP06.pos,STD_SP06.neg).rows;
  $('#lab06-board').innerHTML=`<svg viewBox="0 0 960 540" role="group" aria-label="序列对解码布局"><defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${board(rows,task.outline,{x:70,y:60,w:810,h:415})}</svg>`;
  $('#lab06-graph').innerHTML=result&&result.ok?`<h3>约束分类</h3><table style="width:100%"><tbody>${[...result.graph.H.map(e=>`<tr><td>${esc(e[0])} → ${esc(e[1])}</td><td>水平</td></tr>`),...result.graph.V.map(e=>`<tr><td>${esc(e[0])} → ${esc(e[1])}</td><td>竖直</td></tr>`)].join('')}</tbody></table>`:'<h3>约束图</h3><p>解码后显示。</p>';
  $('#lab06-coords').innerHTML=result&&result.ok?`<h3>坐标与关键前驱</h3><table style="width:100%"><tbody>${result.order.map(id=>{const c=result.coords[id],k=result.key[id];return`<tr><td>${esc(id)}</td><td>(${c.x}, ${c.y}) ${c.w}×${c.h}</td><td>${k.x?'x←'+esc(k.x):''}${k.y?' y←'+esc(k.y):''}</td></tr>`;}).join('')}</tbody></table>`:'<h3>坐标</h3><p>解码后显示。</p>';
  const r=result&&result.ok?result.report:null;
  $('#lab06-metrics').innerHTML=r?`<div class="metric-line"><span>Lab2 检查</span><b>${r.legal?'通过（含外框）':'未通过：'+r.errors.map(describeError02).join('，')}</b></div><div class="metric-line"><span>包围盒</span><b>${r.bbox.width}×${r.bbox.height}=${r.bbox.area}</b></div><div class="metric-line"><span>盒内空余</span><b>${r.bbox_dead??'—'}</b></div>`:'<p class="metric-line">解码失败时没有可评价的布局。</p>';
  const fields=task.id==='decode-eval'?task.fields:task.id==='overflow-sp'?task.fields:[['pos2','第二份编码 pos'],['neg2','第二份编码 neg']];
  $('#lab06-evidence').innerHTML=`<div class="exercise-fields">${fields.map(([key,label])=>`<label>${esc(label)} <input id="lab06-${key}" ${key==='pos2'||key==='neg2'?'class="wide-input" spellcheck="false"':'type="number" step="any"'}></label>`).join('')}</div>`;}
 $('#lab06-task').onchange=e=>load(e.target.value);$('#lab06-reset').onclick=()=>load(task.id);
 $('#lab06-decode').onclick=()=>{task={...task,pos:$('#lab06-pos').value,neg:$('#lab06-neg').value};result=decodeSP06($('#lab06-pos').value,$('#lab06-neg').value);edited=true;render();};
 $('#lab06-hint').onclick=()=>{hint=true;progress.lab06Submissions[task.id]={...(progress.lab06Submissions[task.id]||{}),hintUsed:true};save();$('#lab06-result').textContent=task.hint;};
 $('#lab06-check').onclick=()=>{const e={};for(const key of['ex','ey','ch','w','usable','pos2','neg2'])e[key]=$('#lab06-'+key)?.value;
  const attempt=$('#lab06-pos').value.replace(/\s+/g,'')!==task.startPos.replace(/\s+/g,'')||$('#lab06-neg').value.replace(/\s+/g,'')!==task.startNeg.replace(/\s+/g,'');
  const res=assess06(task.id,{pos:$('#lab06-pos').value,neg:$('#lab06-neg').value,pos2:$('#lab06-pos2')?.value,neg2:$('#lab06-neg2')?.value},e,attempt);
  const explanation=$('#lab06-explanation').value;
  progress.lab06Submissions[task.id]={version:1,pos:$('#lab06-pos').value,neg:$('#lab06-neg').value,evidence:e,numericPassed:res.ok,explanation,hintUsed:hint,explanationStatus:'submitted-not-graded'};save();
  $('#lab06-result').textContent=res.errors.length?res.errors.join('\n'):explanation.trim().length<30?'条件和数值通过，请再写清楚谁约束谁、关键前驱是谁。':'条件和数值通过，解释已保存。请确认你的推理用到了约束方向。';};
 function load(id){task=TASKS06.find(t=>t.id===id);result=null;edited=false;hint=!!progress.lab06Submissions[task.id]?.hintUsed;$('#lab06-result').textContent='';$('#lab06-explanation').value='';render();}
 for(const article of document.querySelectorAll('[data-exercise06]')){const id=article.dataset.exercise06,saved=progress.exercises06[id]||{};for(const input of article.querySelectorAll('[data-field]'))input.value=saved.values?.[input.dataset.field]??'';article.querySelector('[data-explain]').value=saved.explanation||'';let revealed=!!saved.revealed;
  article.querySelector('[data-check]').onclick=()=>{const values=Object.fromEntries([...article.querySelectorAll('[data-field]')].map(e=>[e.dataset.field,e.value])),explanation=article.querySelector('[data-explain]').value,ok=checkExercise06(id,values);progress.exercises06[id]={values,explanation,numericPassed:ok,revealed,explanationStatus:'submitted-not-graded'};save();article.querySelector('[data-result]').textContent=!ok?'数值还不对，请核对取最大值、前驱个数或多对一计数。':explanation.trim().length<30?'数值通过，请补上你的推理。':'数值通过，解释已保存。请按参考要点检查依据。'+(revealed?'（已查看参考）':'');};
  article.querySelector('[data-reveal]').onclick=()=>{revealed=true;article.querySelector('[data-rubric]').hidden=false;progress.exercises06[id]={...(progress.exercises06[id]||{}),revealed:true};save();article.querySelector('[data-result]').textContent='参考要点已显示，不计作独立完成的证明。';};}
 load(TASKS06[0].id);
}
